const input = $input.first().json;
const body = input.body && typeof input.body === 'object' ? input.body : {};
const eventData = body.data && typeof body.data === 'object' ? body.data : {};
const source = { ...body, ...eventData };
const waValue = body.entry?.[0]?.changes?.[0]?.value || {};
const waMessage = waValue.messages?.[0] || {};

const rawSender = source.customer_id ?? source.customerId ?? source.from ?? source.phone ?? waMessage.from ?? input.customer_id ?? '';
let sender = String(rawSender).replace(/\D/g, '');
if (sender.startsWith('01') && sender.length === 11) sender = '88' + sender;

const rawText = source.message ?? source.text?.body ?? source.text ?? waMessage.text?.body ?? input.message ?? '';
const text = String(rawText).trim();
const mediaUrl = source.media_url || source.imageUrl || source.documentUrl || '';
const hasMedia = Boolean(mediaUrl || waMessage.image || waMessage.document);

// Verified True Sellers & Partners list
const sellers = ['8801837183571', '8801973388955', '8801988896991', '8801618742796', '8801746462173'];
const isSeller = sellers.includes(sender) || sender.includes('1837183571') || sender.includes('1973388955');

// Real End-Customers who ordered from you
const customers = [
  {
    "id": "cust_01320824735",
    "phone": "8801320824735",
    "name": "ডিজিটাল সেবা",
    "orders": [
      {
        "applicationNo": "",
        "applicantName": "MD MIZANUR RAHMAN",
        "dob": "05/03/1992",
        "service": "Birth Correction"
      }
    ]
  },
  {
    "id": "cust_01677904285",
    "phone": "8801677904285",
    "name": "Nirob Hossen Zakir",
    "orders": [
      {
        "applicationNo": "",
        "applicantName": "MD SHAHADAT",
        "dob": "19/03/2005",
        "service": "New Birth Registration"
      }
    ]
  },
  {
    "id": "cust_01968946387",
    "phone": "8801968946387",
    "name": "Sb",
    "orders": [
      {
        "applicationNo": "",
        "applicantName": "Khaleda Begum",
        "dob": "06/10/1990",
        "service": "New Birth Registration"
      }
    ]
  }
];

let action = 'IGNORE';
let matchedCustomer = null;
let matchedOrder = null;
let dispatchMessage = '';

if (isSeller) {
  const appMatch = text.match(/\b(26\d{7}|19\d{8})\b/);
  const appNo = appMatch ? appMatch[1] : '';

  if (text.includes('১৭ দেন') || text.includes('17 দেন') || text.includes('bahir kore den') || text.includes('বের করে দেন')) {
    action = 'SELLER_REQUESTED_17_DIGIT';
    dispatchMessage = 'জি ভাই, আবেদনটি পেয়েছি। সার্ভার থেকে ১৭ ডিজিট বের করে আপনাকে দিচ্ছি।';
  } else {
    // Match to customer for auto-dispatching
    for (const cust of customers) {
      for (const ord of cust.orders) {
        if ((appNo && ord.applicationNo === appNo) || (ord.applicantName && text.toLowerCase().includes(ord.applicantName.toLowerCase()))) {
          matchedCustomer = cust;
          matchedOrder = ord;
          break;
        }
      }
      if (matchedCustomer) break;
    }

    if (matchedCustomer) {
      action = 'DISPATCH_TO_CUSTOMER';
      dispatchMessage = `আসসালামু আলাইকুম, আপনার জন্ম নিবন্ধন আবেদন (${matchedOrder.applicantName || appNo}) সফলভাবে সম্পন্ন হয়েছে। অফিসিয়াল কপি নিচে দেওয়া হলো।`;
    } else {
      action = 'SELLER_UPDATE_LOGGED';
    }
  }
} else {
  const appMatch = text.match(/\b(26\d{7}|19\d{8})\b/);
  const isNewApp = appMatch || text.includes('নাম') || text.includes('জন্ম') || text.includes('আবেদন');
  if (isNewApp) {
    action = 'INTAKE_CUSTOMER_ORDER';
    dispatchMessage = 'আপনার আবেদনপত্র ও তথ্য সফলভাবে গ্রহণ করা হয়েছে। ১ দিনের মধ্যে কাজ সম্পন্ন করে সরাসরি WhatsApp-এ অফিসিয়াল PDF সনদ পাঠিয়ে দেওয়া হবে।';
  }
}

return [{
  json: {
    sender,
    isSeller,
    text,
    hasMedia,
    mediaUrl,
    action,
    matchedCustomer,
    matchedOrder,
    dispatchMessage,
    timestamp: new Date().toISOString()
  }
}];
